import random

def wuerfle_faehigkeit():
    return random.choice(["Trab", "Galopp", "Sprung"])

alle_ok = True
for i in range(20):
    f = wuerfle_faehigkeit()
    if f not in ["Trab", "Galopp", "Sprung"]:
        alle_ok = False
print(f"Alle gültig: {alle_ok}")

print(wuerfle_faehigkeit(), wuerfle_faehigkeit(), wuerfle_faehigkeit())

primzahlen = []
for zahl in range(2, 101):
    ist_prim = True
    for teiler in range(2, zahl):
        if zahl % teiler == 0:
            ist_prim = False
    if ist_prim == True:
        primzahlen.append(zahl)

print(f"Anzahl: {len(primzahlen)}")
print(f"Größte: {primzahlen[-1]}")

brett = []
for zeile in range(8):
    reihe = []
    for spalte in range(8):
        if (zeile + spalte) % 2 == 0:
            reihe.append("#")
        else:
            reihe.append(".")
    brett.append(reihe)

print(" ".join(brett[0]))
print(" ".join(brett[1]))

figur = [0, 0]
ziel = [7, 7]
zuege = 0
while True:
    if figur == ziel:
        break
    if figur[1] < 7:
        figur[1] = figur[1] + 1
    else:
        figur[0] = figur[0] + 1
    zuege = zuege + 1

print(f"Züge: {zuege}")
print(f"Ziel erreicht: {figur == ziel}")

